			return message.byteLength;
		} catch (error) {
			return 0;
		}
	} finally {
		writer.dispose();
	}
}

enum State {
	Uninitialized,
	Idle
}

/**
 * An `IChannelServer` hosts a collection of channels. You are
 * able to register channels onto it, provided a channel name.
